package com.bank.transfer.service;

import com.bank.transfer.dto.TransferRequest;
import com.bank.transfer.dto.TransferResponse;
import com.bank.transfer.model.Account;
import com.bank.transfer.repository.AccountRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)  // No Spring context needed — FAST
class TransferServiceTest {

    @Mock
    AccountRepository accountRepo;  // mock — no real database

    @InjectMocks
    TransferService transferService;  // injects mock repo via constructor (IoC in tests!)

    @Test
    void shouldTransferSuccessfully() {
        // Given
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya", new BigDecimal("250000"));

        when(accountRepo.findByIdForUpdate("SAV2001")).thenReturn(Optional.of(rajesh));
        when(accountRepo.findByIdForUpdate("CUR3001")).thenReturn(Optional.of(priya));

        // When
        TransferResponse response = transferService.transfer(
            new TransferRequest("SAV2001", "CUR3001", new BigDecimal("50000"), "Rent"));

        // Then
        assertThat(response.status()).isEqualTo("COMPLETED");
        assertThat(rajesh.getBalance()).isEqualByComparingTo("950000");
        assertThat(priya.getBalance()).isEqualByComparingTo("300000");
        verify(accountRepo, times(2)).save(any(Account.class));
    }
}
