// IoC: define beans, container wires them
@Configuration
class CoreBankingConfig {
  @Bean AccountRepository accountRepository(DataSource ds){ return new JdbcAccountRepository(ds); }
  @Bean AccountService accountService(AccountRepository r){ return new AccountService(r); }
}

// Container hierarchy:
//   BeanFactory (interface) ── getBean(), lazy
//        ▲
//   ApplicationContext (interface) ── adds events, i18n, eager singletons
//        ▲
//   AnnotationConfigApplicationContext (impl used by Spring Boot)

var ctx = new AnnotationConfigApplicationContext(CoreBankingConfig.class);
AccountService svc = ctx.getBean(AccountService.class);   // already instantiated (eager)

// Beans are container-managed singletons by default:
@Service
class AccountService {
  private final AccountRepository repo;                   // injected by IoC, not `new`
  AccountService(AccountRepository repo){ this.repo = repo; }
  Money balance(Long id){ return repo.find(id).balance(); }
}
